def diagonal_sum(mat):
    n = len(mat)
    total = 0
    for i in range(n):
        for j in range(n):
            if i == j or i + j == n - 1:                                   # check every cell to see if it belongs to either diagonal
                total += mat[i][j]
    return total


if __name__ == "__main__":
    print(diagonal_sum([[1, 2, 3], [4, 5, 6], [7, 8, 9]]))

