import java.util.*;

public class Main {
    int diagonalSum(int[][] mat) {
        int n = mat.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j || i + j == n - 1) {                                   // check every cell to see if it belongs to either diagonal
                    total += mat[i][j];
                }
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.diagonalSum(new int[][]{{1, 2, 3}, {4, 5, 6}, {7, 8, 9}}));
    }
}

