def diagonal_sum(mat):
    n = len(mat)
    total = 0
    for i in range(n):
        total += mat[i][i]                                                 # primary diagonal: row i, column i
        j = n - 1 - i                                                      # secondary diagonal: row i, column (n-1-i)
        if j != i:                                                         # avoid double-counting the shared center cell (only happens when n is odd)
            total += mat[i][j]
    return total


if __name__ == "__main__":
    print(diagonal_sum([[1, 2, 3], [4, 5, 6], [7, 8, 9]]))

